import React, { useState, useEffect } from 'react';
import { Alert } from '../common/Alert';
import { parseMatrixText } from '../../utils/matrixParser';

interface MatrixTextInputProps {
    n: number;
    matrix: number[][];
    vector: number[];
    onChange: (matrix: number[][], vector: number[]) => void;
}

export const MatrixTextInput: React.FC<MatrixTextInputProps> = ({
                                                                    n, matrix, vector, onChange
                                                                }) => {
    const [text, setText] = useState<string>('');
    const [error, setError] = useState<string>('');
    const [preview, setPreview] = useState<boolean>(false);

    // При первом рендере или изменении n - генерируем пример
    useEffect(() => {
        generateExample();
    }, [n]);

    const generateExample = () => {
        // Создаём пример с нулями или с простыми числами
        let example = `${n}\n`;
        for (let i = 0; i < n; i++) {
            const row = matrix[i] || Array(n).fill(0);
            const b = vector[i] || 0;
            example += [...row, b].map(v => v.toString()).join(' ') + '\n';
        }
        setText(example.trim());
        setError('');
    };

    const handleTextChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
        setText(e.target.value);
        setError('');
    };

    const handleParse = () => {
        try {
            const result = parseMatrixText(text);

            // Проверяем размерность
            if (result.n > 20) {
                setError('Размерность матрицы не должна превышать 20');
                return;
            }

            onChange(result.matrix, result.vector);
            setError('');

        } catch (err) {
            setError((err as Error).message);
        }
    };

    const handleClear = () => {
        setText('');
        setError('');
    };

    return (
        <div className="space-y-4">
            <div className="flex items-center justify-between">
                <label className="block text-sm font-medium text-gray-700">
                    Введите матрицу в текстовом формате:
                </label>
                <div className="flex gap-2">
                    <button
                        onClick={() => setPreview(!preview)}
                        className="text-sm text-blue-600 hover:text-blue-800"
                    >
                        {preview ? 'Скрыть пример' : 'Показать пример'}
                    </button>
                    <button
                        onClick={generateExample}
                        className="text-sm text-gray-600 hover:text-gray-800"
                    >
                        Сбросить
                    </button>
                </div>
            </div>

            {preview && (
                <div className="bg-blue-50 border border-blue-200 rounded-md p-3 text-sm">
                    <p className="font-medium text-blue-700 mb-1">Формат ввода:</p>
                    <p className="text-blue-600 font-mono text-xs">
                        [размерность n]<br />
                        a₁₁ a₁₂ ... a₁ₙ b₁<br />
                        a₂₁ a₂₂ ... a₂ₙ b₂<br />
                        ...<br />
                        aₙ₁ aₙ₂ ... aₙₙ bₙ
                    </p>
                    <p className="text-blue-600 mt-2 text-xs">
                        Пример для n=3:<br />
                        <span className="font-mono">
                            3<br />
                            2 1 -1 8<br />
                            -3 -1 2 -11<br />
                            -2 1 2 -3
                        </span>
                    </p>
                </div>
            )}

            <textarea
                value={text}
                onChange={handleTextChange}
                rows={n + 2}
                className="w-full px-3 py-2 border border-gray-300 rounded-md font-mono text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
                placeholder="Введите матрицу..."
                spellCheck={false}
            />

            {error && (
                <Alert type="error" message={error} />
            )}

            <div className="flex gap-2">
                <button
                    onClick={handleParse}
                    className="flex-1 bg-blue-600 text-white rounded-md hover:bg-blue-700 transition-colors py-2"
                >
                    Применить матрицу
                </button>
                <button
                    onClick={handleClear}
                    className="px-4 py-2 bg-gray-200 text-gray-700 rounded-md hover:bg-gray-300 transition-colors"
                >
                    Очистить
                </button>
            </div>

            <p className="text-xs text-gray-500">
                * Числа разделяются пробелами, табуляцией или переносом строки.<br />
                * Можно скопировать прямо из файла или Excel.
            </p>
        </div>
    );
};
